INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_DRUZE','Druze Tradition (Fatimid origins to present)',1017,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_ABU_IZZEDDIN_DRUZES','secondary scholarship','Nejla M. Abu-Izzeddin, The Druzes: A New Study of Their History, Faith and Society (Brill, 1984)','Druze history, doctrine of tawhid, the hudud, al-Hakim, al-Darazi, Hamza, transmigration'),
 ('SRC_FIRRO_DRUZES','secondary scholarship','Kais M. Firro, A History of the Druzes (Brill, 1992)','Druze social and political history; community formation in the Levant'),
 ('SRC_DAFTARY_ISMAILIS','secondary scholarship','Farhad Daftary, The Ismailis: Their History and Doctrines, 2nd ed. (Cambridge UP, 2007)','Fatimid Ismaili background; al-Hakim''s reign; the Druze schism')
INSERT INTO _e VALUES
 ('ENT_DRZ_HUDUD','Al-Hudud al-Khamsa (The Five Cosmic Luminaries)','collective','emanation hierarchy','Druze','cosmology','B','Collective hub: the five cosmic ranks (al-hudud al-ulwiyya) through which the divine unity is mediated in Druze cosmology; attested in Abu-Izzeddin and standard scholarship.'),
 ('ENT_DRZ_AL_AQL','Al-Aql al-Kulli (the Universal Intellect)','hypostasis','luminary','Druze','cosmology','B','First and highest of the five luminaries, the Universal Intellect; held to be manifested in Hamza ibn Ali. Attested doctrine.'),
 ('ENT_DRZ_AL_NAFS','Al-Nafs al-Kulliyya (the Universal Soul)','hypostasis','luminary','Druze','cosmology','B','Second luminary, the Universal Soul, emanating from the Intellect; associated with Abu Ibrahim Isma''il al-Tamimi.'),
 ('ENT_DRZ_AL_KALIMA','Al-Kalima (the Word)','hypostasis','luminary','Druze','cosmology','B','Third luminary, the Word/Logos; associated with Muhammad ibn Wahb al-Tamimi. Attested.'),
 ('ENT_DRZ_AL_SABIQ','Al-Sabiq (the Preceder / Right Wing)','hypostasis','luminary','Druze','cosmology','B','Fourth luminary, the Preceder (also ''the Right Wing''); associated with Salama ibn Abd al-Wahhab. Attested.'),
 ('ENT_DRZ_AL_TALI','Al-Tali (the Follower / Left Wing)','hypostasis','luminary','Druze','cosmology','B','Fifth luminary, the Follower (also ''the Left Wing''); associated with Baha al-Din al-Muqtana. Attested.'),
 ('ENT_DRZ_HAMZA','Hamza ibn Ali ibn Ahmad','person','luminary-incarnation','Druze','founder','B','Persian founder-theologian of the Druze daʿwa (fl. 1017-21); chief organizer, held as the human manifestation of al-Aql (Universal Intellect). Historically attested. HOMONYM: distinct from ENT_ISL_HAMZA (Hamza ibn Abd al-Muttalib, uncle of the Prophet Muhammad).'),
 ('ENT_DRZ_ABU_IBRAHIM','Abu Ibrahim Isma''il al-Tamimi','person','luminary-incarnation','Druze','founder','C','Early Druze daʿi associated with the rank of al-Nafs (Universal Soul). Attested in Druze epistolary tradition.'),
 ('ENT_DRZ_AL_TAMIMI','Muhammad ibn Wahb al-Qurashi al-Tamimi','person','luminary-incarnation','Druze','founder','C','Early Druze daʿi associated with the rank of al-Kalima (the Word). HOMONYM: distinct from the Prophet Muhammad (ENT_ISL_MUHAMMAD).'),
 ('ENT_DRZ_SALAMA','Salama ibn Abd al-Wahhab','person','luminary-incarnation','Druze','founder','C','Early Druze daʿi associated with the rank of al-Sabiq (the Preceder). Attested.'),
 ('ENT_DRZ_MUQTANA','Baha al-Din al-Muqtana al-Samuqi','person','luminary-incarnation','Druze','founder','B','Druze daʿi (fl. 1027-43) who compiled much of the Rasaʾil al-Hikma (Epistles of Wisdom) and sealed the daʿwa; held as the manifestation of al-Tali (the Follower). Attested.'),
 ('ENT_DRZ_AL_HAKIM','Al-Hakim bi-Amr Allah','person','divine-manifestation','Druze','theophany','B','Sixth Fatimid caliph-imam (r.996-1021); in Druze belief the manifestation (mazhar/tajalli) of the divine unity. Historically attested Fatimid ruler; his divinity is a confessional Druze claim, modeled descriptively.'),
 ('ENT_DRZ_AL_DARAZI','Muhammad al-Darazi (Nashtakin al-Darazi)','person','heresiarch','Druze','founder','B','Early daʿi (d. c.1018) whose extremist preaching gave the community its exonym ''Druze''; later repudiated by Hamza as a heretic. Historically attested.'),
 ('ENT_DRZ_TAQAMMUS','Taqammus (transmigration of souls)','concept','doctrine','Druze','soteriology','B','Druze doctrine that the fixed number of souls transmigrate immediately from body to body (taqammus); a defining publicly attested tenet.'),
 ('ENT_DRZ_TAWHID','Tawhid (the Druze doctrine of divine unity)','concept','doctrine','Druze','theology','B','The unitarian core from which the Druze self-designation Muwahhidun (''Unitarians'') derives; God beyond attributes, mediated through the hudud. Attested.'),
 ('ENT_DRZ_RASAIL','Rasaʾil al-Hikma (Epistles of Wisdom)','text','canon','Druze','scripture','B','The 111-epistle Druze sacred canon, largely by Hamza and al-Muqtana; foundational closed scripture. Existence and authorship attested in scholarship.');
