INSERT INTO _r VALUES
 ('ENT_DRZ_AL_AQL','member_of','ENT_DRZ_HUDUD','high','Al-Aql is the first of the five cosmic luminaries (al-hudud).'),
 ('ENT_DRZ_AL_NAFS','member_of','ENT_DRZ_HUDUD','high','Al-Nafs is the second of the five luminaries.'),
 ('ENT_DRZ_AL_KALIMA','member_of','ENT_DRZ_HUDUD','high','Al-Kalima is the third of the five luminaries.'),
 ('ENT_DRZ_AL_SABIQ','member_of','ENT_DRZ_HUDUD','high','Al-Sabiq is the fourth of the five luminaries.'),
 ('ENT_DRZ_AL_TALI','member_of','ENT_DRZ_HUDUD','high','Al-Tali is the fifth of the five luminaries.'),
 ('ENT_DRZ_AL_NAFS','emanates_from','ENT_DRZ_AL_AQL','high','In Druze cosmology the Universal Soul emanates from the Universal Intellect.'),
 ('ENT_DRZ_AL_KALIMA','emanates_from','ENT_DRZ_AL_NAFS','high','The Word emanates from the Universal Soul in the descending hierarchy of luminaries.'),
 ('ENT_DRZ_AL_SABIQ','emanates_from','ENT_DRZ_AL_KALIMA','high','The Preceder emanates from the Word.'),
 ('ENT_DRZ_AL_TALI','emanates_from','ENT_DRZ_AL_SABIQ','high','The Follower emanates from the Preceder, completing the five ranks.'),
 ('ENT_DRZ_HAMZA','embodies','ENT_DRZ_AL_AQL','high','Hamza ibn Ali is held to be the human manifestation of al-Aql, the Universal Intellect.'),
 ('ENT_DRZ_ABU_IBRAHIM','embodies','ENT_DRZ_AL_NAFS','medium','Abu Ibrahim al-Tamimi is associated with the rank of al-Nafs.'),
 ('ENT_DRZ_AL_TAMIMI','embodies','ENT_DRZ_AL_KALIMA','medium','Muhammad ibn Wahb al-Tamimi is associated with the rank of al-Kalima.'),
 ('ENT_DRZ_SALAMA','embodies','ENT_DRZ_AL_SABIQ','medium','Salama ibn Abd al-Wahhab is associated with the rank of al-Sabiq.'),
 ('ENT_DRZ_MUQTANA','embodies','ENT_DRZ_AL_TALI','high','Baha al-Din al-Muqtana is held to be the manifestation of al-Tali, the Follower.'),
 ('ENT_DRZ_HAMZA','member_of','ENT_DRZ_HUDUD','high','As manifestation of al-Aql, Hamza is the human head of the five luminaries.'),
 ('ENT_DRZ_MUQTANA','member_of','ENT_DRZ_HUDUD','high','As manifestation of al-Tali, al-Muqtana belongs to the five luminaries.'),
 ('ENT_DRZ_AL_HAKIM','presides_over','ENT_DRZ_HUDUD','high','In Druze belief al-Hakim, as divine manifestation, stands above and is served by the five cosmic luminaries.'),
 ('ENT_DRZ_HAMZA','transmits','ENT_DRZ_RASAIL','medium','Hamza authored/transmitted a major portion of the epistles collected in the Rasaʾil al-Hikma.'),
 ('ENT_DRZ_MUQTANA','transmits','ENT_DRZ_RASAIL','medium','Al-Muqtana compiled and transmitted many of the epistles of the Rasaʾil al-Hikma.'),
 ('ENT_DRZ_HAMZA','reveals','ENT_DRZ_TAWHID','high','Hamza systematized and proclaimed the Druze doctrine of tawhid.'),
 ('ENT_DRZ_TAQAMMUS','member_of','ENT_DRZ_TAWHID','medium','Taqammus is an integral doctrine within the Druze tawhid worldview.'),
 ('ENT_DRZ_AL_DARAZI','opposes','ENT_DRZ_HAMZA','high','Al-Darazi''s extremist claims were repudiated by Hamza, who declared him a heretic; the two were rivals in the early daʿwa.'),
 ('ENT_DRZ_TAWHID','reception_of','ENT_ISL_ALLAH','high','Druze tawhid develops the Islamic affirmation of God''s absolute unity (Allah) in a distinctive transcendent direction.'),
 ('ENT_DRZ_AL_HAKIM','reception_of','ENT_ISL_IMAMAH','high','Druze veneration of al-Hakim derives from the Fatimid Ismaili doctrine of the imamate (imamah), radicalized into a claim of divine manifestation.'),
 ('ENT_DRZ_HAMZA','reception_of','ENT_OCCULTATION','medium','Druze expectation of the return of al-Hakim and Hamza adapts the Shia doctrine of occultation (ghayba) and awaited return.'),
 ('ENT_DRZ_AL_AQL','aligned_with','ENT_GNO_NOUS','medium','The Druze Universal Intellect (al-Aql al-Kulli) is functionally cognate to the Neoplatonic/Gnostic Nous as first emanation, a comparison drawn in scholarship on Ismaili-Druze cosmology.');
